def _speed_stage_start(
    name: str,
) -> tuple[str, torch.cuda.Event] | None:
    if not _SPEED_STAGE_PROFILE_ENABLED:
        return None
    event = torch.cuda.Event(enable_timing=True)
    event.record()
    return name, event


def _speed_stage_stop(
    handle: tuple[str, torch.cuda.Event] | None,
) -> None:
    if handle is None:
        return
    stop = torch.cuda.Event(enable_timing=True)
    stop.record()
    _SPEED_STAGE_EVENTS.append((handle[0], handle[1], stop))


def consume_speed_stage_timings() -> dict[str, float]:
    if not _SPEED_STAGE_EVENTS:
        return {}
    rows = list(_SPEED_STAGE_EVENTS)
    _SPEED_STAGE_EVENTS.clear()
    totals: dict[str, float] = {}
    for name, start, stop in rows:
        totals[name] = totals.get(name, 0.0) + float(
            start.elapsed_time(stop)
        )
    return totals
